<?php
namespace App\Domain\Industries;
use App\Domain\Homepage\HomepageCache; use App\Domain\PublicChrome\PublicChromeCache; use App\Models\{HomepageItem,NavigationItem}; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Throwable;
final class IndustryCache { public static function version(int $id):int{try{return (int)Cache::rememberForever("public.industries.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function indexVersion():int{try{return (int)Cache::rememberForever('public.industries.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function forget(int $id):void{try{Cache::put("public.industries.version.$id",hrtime(true));Cache::put('public.industries.index.version',hrtime(true));if(HomepageItem::where('industry_id',$id)->exists())HomepageCache::forget();if(NavigationItem::where('industry_id',$id)->exists())PublicChromeCache::forgetAll();}catch(Throwable){}} public static function forgetRelated(string $table,string $column,int $id):void{try{if(!Schema::hasTable($table)){return;}DB::table($table)->where($column,$id)->pluck('industry_id')->each(fn($industryId)=>self::forget((int)$industryId));}catch(Throwable){}} }
